CREATE TABLE aluno (matricula INTEGER PRIMARY KEY, nome TEXT, curso TEXT);
INSERT INTO aluno VALUES (1, 'Ana', 'BCC'), (2, 'Davi', 'SI');
CREATE VIEW aluno_bcc AS
  SELECT matricula, nome FROM aluno WHERE curso = 'BCC';
SELECT nome FROM aluno_bcc;
ALTER TABLE aluno ADD COLUMN email TEXT;
SELECT nome FROM aluno_bcc;

